<template><section class="change-page"><div class="heading"><div><span>BOOKING CHANGES</span><h2>预约变更申请</h2><p>集中处理用户的改期和取消申请。</p></div><div><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option label="待处理" value="pending"/><el-option label="已批准" value="approved"/><el-option label="已驳回" value="rejected"/></el-select><el-button @click="load" :loading="loading">刷新</el-button></div></div><el-table :data="items" v-loading="loading" border empty-text="暂无变更申请"><el-table-column prop="id" label="编号" width="80"/><el-table-column prop="request_type" label="申请类型" width="100"><template #default="s"><el-tag :type="s.row.request_type==='cancel'?'danger':'warning'">{{s.row.request_type==='cancel'?'取消预约':'申请改期'}}</el-tag></template></el-table-column><el-table-column prop="yonghuxingming" label="客户" min-width="110"/><el-table-column prop="sheyingxingming" label="摄影师" min-width="110"/><el-table-column label="原安排" min-width="170"><template #default="s">{{s.row.yuyuesheyingriqi}} {{s.row.yuyueshijianduan}}</template></el-table-column><el-table-column label="申请安排" min-width="170"><template #default="s">{{s.row.requested_date||'—'}} {{s.row.requested_slot||''}}</template></el-table-column><el-table-column prop="reason" label="原因" min-width="180" show-overflow-tooltip/><el-table-column prop="status" label="状态" width="100"><template #default="s"><el-tag>{{labels[s.row.status]||s.row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="190"><template #default="s"><el-button v-if="s.row.status==='pending'" size="small" type="primary" @click="handle(s.row,'approve')">批准</el-button><el-button v-if="s.row.status==='pending'" size="small" type="danger" plain @click="handle(s.row,'reject')">驳回</el-button></template></el-table-column></el-table></section></template>
<script setup>
import {ref,onMounted,getCurrentInstance} from 'vue'
import {ElMessageBox} from 'element-plus'
const ctx=getCurrentInstance().appContext.config.globalProperties,items=ref([]),loading=ref(false),status=ref('pending'),labels={pending:'待处理',approved:'已批准',rejected:'已驳回'}
async function load(){loading.value=true;try{const r=await ctx.$http.get('sheyingshiyuyue/change-requests',{params:{status:status.value}});items.value=r.data.data||[]}finally{loading.value=false}}
async function handle(row,action){let note='';try{const r=await ElMessageBox.prompt(action==='approve'?'可填写处理说明':'请填写驳回原因',action==='approve'?'批准申请':'驳回申请',{confirmButtonText:'提交',cancelButtonText:'取消',inputPlaceholder:'处理说明'});note=r.value||''}catch{return}try{await ctx.$http.post('sheyingshiyuyue/change-requests/'+row.id+'/handle',{action,note});ctx.$toolUtil.message('处理完成','success');load()}catch(e){ctx.$toolUtil.message(e?.data?.msg||e?.response?.data?.msg||'处理失败','error')}}onMounted(load)
</script><style scoped>.change-page{padding:4px 0 28px}.heading{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:20px}.heading span{font-size:11px;letter-spacing:.15em;color:#82907f}.heading h2{margin:7px 0 4px;color:#294a3b}.heading p{margin:0;color:#849083;font-size:13px}.heading>div:last-child{display:flex;gap:10px}.change-page :deep(.el-table){border-radius:8px;overflow:hidden}@media(max-width:760px){.heading{display:block}.heading>div:last-child{margin-top:14px}}
</style>
